business as (select
    CAST(NULL AS Nullable(DateTime64(3,'UTC'))) AS `source_published_at`,
    CAST([] AS Array(String)) AS `source_version_keys`,
    CAST(followup_definition_id AS String) AS `followup_definition_id`,
    CAST({{ ch_literal(var('source_tenant_id','demo_crm')) }} AS String) AS `tenant_id`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('followup_definition_v1',tuple('tenant_id','String',if(isNull(tenant_id),'1','0'),ifNull(toString(tenant_id),'')),tuple('followup_definition_id','String',if(isNull(followup_definition_id),'1','0'),ifNull(toString(followup_definition_id),'')))))))) AS String) AS `followup_definition_key`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('followup_definition_version_v1',tuple('followup_definition_key','String',if(isNull(followup_definition_key),'1','0'),ifNull(toString(followup_definition_key),'')),tuple('definition_rule_version','String',if(isNull(definition_rule_version),'1','0'),ifNull(toString(definition_rule_version),'')))))))) AS String) AS `followup_definition_version_key`,
    CAST({{ ch_literal(var('rule_version','parse_only')) }} AS String) AS `definition_rule_version`,
    CAST(followup_kind AS String) AS `followup_kind`,
    CAST(sale_type_id AS Int64) AS `sale_type_id`,
    CAST(source_stage_id AS Nullable(Int64)) AS `source_stage_id`,
    CAST(target_stage_id AS Nullable(Int64)) AS `target_stage_id`,
    CAST(horizon_days AS Nullable(UInt16)) AS `horizon_days`,
    CAST(funnel_position AS Nullable(UInt16)) AS `funnel_position`,
    CAST(previous_target_stage_id AS Nullable(Int64)) AS `previous_target_stage_id`,
    CAST(if(followup_kind='stage_transition','first_admissible_stage_entry','created_at') AS String) AS `anchor_rule`,
    CAST(concat('sale_type_',toString(sale_type_id)) AS String) AS `population_rule`,
    CAST('context_at_anchor' AS String) AS `attribution_rule`,
    CAST('whole_cohort_before_filters' AS String) AS `maturity_rule`,
    CAST(true AS Bool) AS `is_enabled`,
    CAST('ready' AS String) AS `definition_status`
from definitions),
keyed as (select
    `source_published_at`,
    `source_version_keys`,
    `followup_definition_id`,
    `tenant_id`,
    `followup_definition_key`,
    `followup_definition_version_key`,
    `definition_rule_version`,
    `followup_kind`,
    `sale_type_id`,
    `source_stage_id`,
    `target_stage_id`,
    `horizon_days`,
    `funnel_position`,
    `previous_target_stage_id`,
    `anchor_rule`,
    `population_rule`,
    `attribution_rule`,
    `maturity_rule`,
    `is_enabled`,
    `definition_status`,
    {{ ch_literal(var('model_run_id','parse_only')) }} as model_run_id,
    followup_definition_version_key as record_key,
    {{ utc_var('calculated_at') }} as calculated_at,
    {{ ch_literal(var('rule_version','parse_only')) }} as rule_version,
    {{ utc_var('input_cutoff_at') }} as input_cutoff_at,
    cityHash64(record_key) % {{ var('write_batch_count',1)|int }} as __write_bucket
from business),
