    {{ typed_hash('dim_followup_definition:row_v1', [{'name': 'source_published_at', 'type': "Nullable(DateTime64(3,'UTC'))", 'expr': 'source_published_at'}, {'name': 'source_version_keys', 'type': 'Array(String)', 'expr': 'source_version_keys'}, {'name': 'followup_definition_id', 'type': 'String', 'expr': 'followup_definition_id'}, {'name': 'tenant_id', 'type': 'String', 'expr': 'tenant_id'}, {'name': 'followup_definition_key', 'type': 'String', 'expr': 'followup_definition_key'}, {'name': 'followup_definition_version_key', 'type': 'String', 'expr': 'followup_definition_version_key'}, {'name': 'definition_rule_version', 'type': 'String', 'expr': 'definition_rule_version'}, {'name': 'followup_kind', 'type': 'String', 'expr': 'followup_kind'}, {'name': 'sale_type_id', 'type': 'Int64', 'expr': 'sale_type_id'}, {'name': 'source_stage_id', 'type': 'Nullable(Int64)', 'expr': 'source_stage_id'}, {'name': 'target_stage_id', 'type': 'Nullable(Int64)', 'expr': 'target_stage_id'}, {'name': 'horizon_days', 'type': 'Nullable(UInt16)', 'expr': 'horizon_days'}, {'name': 'funnel_position', 'type': 'Nullable(UInt16)', 'expr': 'funnel_position'}, {'name': 'previous_target_stage_id', 'type': 'Nullable(Int64)', 'expr': 'previous_target_stage_id'}, {'name': 'anchor_rule', 'type': 'String', 'expr': 'anchor_rule'}, {'name': 'population_rule', 'type': 'String', 'expr': 'population_rule'}, {'name': 'attribution_rule', 'type': 'String', 'expr': 'attribution_rule'}, {'name': 'maturity_rule', 'type': 'String', 'expr': 'maturity_rule'}, {'name': 'is_enabled', 'type': 'Bool', 'expr': 'is_enabled'}, {'name': 'definition_status', 'type': 'String', 'expr': 'definition_status'}]) }} as row_hash from selected_rows),
candidate as (select
    `model_run_id`,
    `record_key`,
    `row_hash`,
    `calculated_at`,
    `rule_version`,
    `input_cutoff_at`,
